from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from pathlib import Path
doc=Document()
s=doc.sections[0];s.page_height=Cm(29.7);s.page_width=Cm(21);s.top_margin=Cm(2);s.bottom_margin=Cm(2);s.left_margin=Cm(2.5);s.right_margin=Cm(2)
for name in ['Normal','Title','Heading 1','Heading 2']:
 st=doc.styles[name];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0)
doc.styles['Normal'].font.size=Pt(12)
doc.styles['Normal'].paragraph_format.space_after=Pt(6)
doc.styles['Normal'].paragraph_format.line_spacing=1.12
doc.styles['Heading 1'].font.size=Pt(17);doc.styles['Heading 2'].font.size=Pt(13)
footer=s.footer.paragraphs[0];footer.alignment=2
footer.add_run('FoodNow | ')
f=OxmlElement('w:fldSimple');f.set(qn('w:instr'),'PAGE');footer._p.append(f)
def p(t):doc.add_paragraph(t)
def h(t):doc.add_heading(t,2)
def page(t):
 doc.add_page_break();doc.add_heading(t,1)
def table(head,rows):
 t=doc.add_table(rows=1, cols=len(head));t.style='Table Grid'
 for c,v in zip(t.rows[0].cells,head):c.text=v
 for row in rows:
  for c,v in zip(t.add_row().cells,row):c.text=str(v)
 for row in t.rows:
  for c in row.cells:
   for para in c.paragraphs:
    para.paragraph_format.space_after=Pt(3)
    for run in para.runs:run.font.size=Pt(10)
 for c in t.rows[0].cells:
  shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'E7E6E6');c._tc.get_or_add_tcPr().append(shade)
  for r in c.paragraphs[0].runs:r.bold=True
 p('')
def fig(n,text):
 para=doc.add_paragraph();para.paragraph_format.space_before=Pt(9);para.paragraph_format.space_after=Pt(10)
 para.add_run(f'[CHÈN ẢNH MINH CHỨNG {n}]\n').bold=True
 para.add_run(text+'\nThay đoạn giữ chỗ này bằng ảnh chụp thực tế.').italic=True
 props=para._p.get_or_add_pPr();shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'F2F2F2');props.append(shade)
def feature(title,body):h(title);p(body)
doc.add_paragraph('BÁO CÁO ỨNG DỤNG FOODNOW',style='Title')
p('Ứng dụng đặt món và quản lý giao hàng trên Android')
p('Môn học: ...........................................................')
p('Sinh viên: ..........................................................')
p('Mã sinh viên: .......................................................')
p('Lớp: ................................................................')
p('Giảng viên: ........................................................')
p('Ngày cập nhật: 05 tháng 11 năm 2026')
h('Nội dung báo cáo')
p('Báo cáo trình bày chức năng của FoodNow theo ba vai trò: khách hàng, quản trị viên và người giao hàng. Nội dung gồm cách sử dụng, luồng xử lý, tổ chức dữ liệu Firebase, phân quyền và các tình huống kiểm thử. Ứng dụng phục vụ bài thực hành; thanh toán và tiến độ giao hàng được mô phỏng.')
table(['Phần','Nội dung'],[['1','Tổng quan và kiến trúc'],['2','Tài khoản và chức năng dùng chung'],['3','Luồng khách hàng'],['4','Luồng quản trị viên'],['5','Luồng người giao hàng'],['6','Cấu trúc và quan hệ dữ liệu'],['7','Phân quyền và đồng bộ'],['8','Kiểm thử và minh chứng'],['9','Giới hạn và hướng phát triển']])
page('1 Tổng quan và kiến trúc')
feature('1 1 Mục tiêu','FoodNow cho phép khách hàng xem nhà hàng, chọn món và đặt đơn. Quản trị viên quản lý danh mục, tài khoản, đơn hàng và thống kê. Người giao hàng nhận đơn, cập nhật quá trình giao và xem các đơn đã hoàn tất. Ba vai trò cùng sử dụng dữ liệu trên Firebase để theo dõi thay đổi giữa các thiết bị.')
table(['Thành phần','Vai trò trong ứng dụng'],[['Android Java và XML','Xử lý chức năng và xây dựng giao diện'],['Firebase Authentication','Đăng ký, đăng nhập và quản lý mật khẩu'],['Firebase Realtime Database','Lưu hồ sơ, nhà hàng, món, topping và đơn hàng'],['CloudRepository','Đọc ghi dữ liệu, giữ dữ liệu đang hiển thị và nhận cập nhật'],['Security Rules','Kiểm soát quyền đọc ghi theo UID và vai trò'],['Tài nguyên drawable','Lưu ảnh món, biểu tượng và logo trong APK']])
feature('1 2 Cách các thành phần làm việc','Người dùng thao tác trên màn hình Android. Firebase Authentication xác nhận tài khoản và cung cấp UID. Ứng dụng đọc hồ sơ users/{UID} để biết vai trò, sau đó mở màn hình phù hợp. CloudRepository gửi thao tác dữ liệu đến Realtime Database; Security Rules kiểm tra quyền trước khi chấp nhận. Listener nhận thay đổi để cập nhật màn hình.')
p('Luồng tổng quát: Giao diện Android → Firebase Authentication → hồ sơ users/{UID} → CloudRepository ↔ Realtime Database → cập nhật giao diện.')
feature('1 3 Phạm vi dữ liệu hiện có','Bộ dữ liệu đã nạp gồm 4 nhà hàng, 16 món, 9 topping và 6 đơn mẫu. Các thương hiệu gồm 7-Eleven, KFC, Circle K và Highlands Coffee. Giá, địa chỉ và món ăn chỉ dùng minh họa, không đại diện cho thông tin kinh doanh chính thức. Ba hồ sơ demo có vai trò admin, user và shipper.')
fig('01','Chụp màn hình danh sách nhà hàng và cây dữ liệu Firebase gồm users, restaurants, foods, options, orders.')
page('2 Tài khoản và chức năng dùng chung')
feature('2 1 Đăng ký','Người dùng nhập họ tên, email và mật khẩu. Firebase Authentication tạo tài khoản; ứng dụng tạo hồ sơ cùng UID trong users với role là user. Nếu email đã tồn tại hoặc thông tin không hợp lệ, ứng dụng hiển thị lỗi. Tài khoản đăng ký thông thường không được tự chọn quyền admin hay shipper.')
feature('2 2 Đăng nhập và phân vai trò','Ứng dụng xác thực email và mật khẩu bằng Firebase Authentication, đọc hồ sơ cùng UID, kiểm tra disabled và role rồi đồng bộ dữ liệu ban đầu. role=user mở màn hình khách hàng; role=admin mở màn hình quản trị; role=shipper mở màn hình giao hàng. Có tài khoản Authentication nhưng thiếu hồ sơ Realtime Database thì chưa đủ điều kiện sử dụng app.')
feature('2 3 Quên mật khẩu và đổi mật khẩu','Quên mật khẩu sử dụng email đặt lại do Firebase gửi, vì vậy người dùng cần truy cập được hộp thư. Trong phần hồ sơ, đổi mật khẩu yêu cầu xác thực lại bằng mật khẩu hiện tại trước khi cập nhật mật khẩu mới. Không lưu mật khẩu trong hồ sơ users và không có chức năng xem lại mật khẩu gốc.')
feature('2 4 Hồ sơ cá nhân và đăng xuất','Khách hàng xem thông tin cá nhân, đổi tên hiển thị và chọn ảnh đại diện có sẵn. Thay đổi được ghi vào hồ sơ đúng UID. Khi đăng xuất, ứng dụng kết thúc phiên Firebase, ngừng đồng bộ và trở về màn hình đăng nhập. Khi tài khoản bị khóa hoặc quyền thay đổi trong phiên, ứng dụng yêu cầu đăng nhập lại.')
table(['Vai trò','Tài khoản demo','Điều kiện sử dụng'],[['Khách hàng','user@gmail.com','Có hồ sơ role=user'],['Quản trị viên','admin@gmail.com','Có hồ sơ role=admin'],['Người giao hàng','shipper@gmail.com','Có hồ sơ role=shipper']])
p('Mật khẩu demo được bàn giao riêng. Không đưa mật khẩu hay mã phiên đăng nhập vào ảnh minh chứng của báo cáo.')
fig('02','Chụp màn hình đăng nhập và thông báo khi nhập sai thông tin. Che mật khẩu nếu đang hiển thị.')
fig('03','Chụp hồ sơ cá nhân và hộp thoại đổi mật khẩu hoặc chỉnh sửa hồ sơ.')
page('3 Luồng khách hàng xem và chọn món')
feature('3 1 Xem danh sách nhà hàng','Sau khi đăng nhập, khách hàng xem các nhà hàng gồm tên, logo và địa chỉ. Khi chọn một nhà hàng, ứng dụng mở danh sách các món có restaurantKey trỏ tới nhà hàng đó. Logo được lấy từ tài nguyên trong APK thông qua tên lưu trên Firebase.')
feature('3 2 Xem và tìm món','Danh sách món hiển thị tên, ảnh và giá. Khách hàng có thể tìm trong danh sách món của nhà hàng. Trạng thái available cho biết món còn được bán hay không. Việc chọn món cần dựa trên dữ liệu hiện tại; khi ghi đơn, ứng dụng kiểm tra món còn tồn tại và còn bán.')
feature('3 3 Chi tiết món và topping','Chọn món để xem thông tin chi tiết, chỉnh số lượng và chọn các topping. Mỗi topping có tên và giá cộng thêm. Số lượng được giới hạn tối đa 99. Tổng tiền của lựa chọn được tính từ giá món, các topping đã chọn và số lượng; thao tác tạo đơn kiểm tra giới hạn tổng tiền của ứng dụng.')
p('Công thức: tiền một lựa chọn = (giá món + tổng giá topping đã chọn) × số lượng. Ví dụ minh họa: món 59.000 đồng, topping 5.000 đồng và số lượng 2 thì thành tiền là 128.000 đồng.')
feature('3 4 Giỏ hàng','Các lựa chọn được giữ trong giỏ của màn hình đặt món. Tổng giỏ bằng tổng tiền các lựa chọn. Khi danh mục thay đổi trong lúc đang chọn món, ứng dụng có thể xóa giỏ và thông báo chọn lại để tránh dùng giá hoặc topping đã cũ. Giỏ không phải là một nhánh dữ liệu được lưu trên Firebase và chưa bảo đảm khôi phục sau khi đóng ứng dụng.')
fig('04','Chụp danh sách món của một nhà hàng, có tên món và giá rõ ràng.')
fig('05','Chụp hộp thoại món với topping, số lượng và tổng tiền. Có thể dùng ví dụ 2 phần để minh họa phép tính.')
page('3 Luồng khách hàng đặt và theo dõi đơn')
feature('3 5 Thanh toán mô phỏng','Khi chọn đặt hàng, ứng dụng mở lựa chọn mô phỏng thành công, thất bại hoặc hủy. Chỉ nhánh thành công mới ghi đơn lên Firebase. Thất bại hoặc hủy giữ lại giỏ hàng. Đây là thao tác giả lập, không liên kết ngân hàng, không trừ tiền và không xác nhận một giao dịch thanh toán thực.')
feature('3 6 Tạo đơn','Đơn được cấp khóa Firebase mới và chứa UID người đặt, email, danh sách món, tổng tiền, thời gian và trạng thái Chờ xác nhận. paymentStatus có giá trị simulated_paid. Ứng dụng thông báo thành công sau khi Firebase xác nhận ghi dữ liệu; nếu ghi lỗi, giỏ được giữ để người dùng thử lại.')
feature('3 7 Theo dõi và hủy đơn','Khách hàng xem các đơn thuộc UID của mình. Khi shipper nhận đơn, trạng thái chuyển sang Đang giao; tiến độ được cập nhật theo mô phỏng. Khách hàng có thể hủy đơn còn Chờ xác nhận và xác nhận hoàn thành đơn đang giao. Đơn đã bị hủy không còn là đơn chờ nhận của shipper.')
h('3 8 Trình tự thực hiện đầy đủ')
p('Bước 1: Đăng nhập user@gmail.com. Bước 2: Chọn nhà hàng và món. Bước 3: Chọn topping, số lượng rồi thêm vào giỏ. Bước 4: Chọn thanh toán mô phỏng thành công. Bước 5: Kiểm tra đơn trong lịch sử. Bước 6: Chờ shipper nhận và cập nhật. Bước 7: Xác nhận hoàn thành hoặc kiểm tra trạng thái hoàn tất sau khi shipper hoàn thành.')
fig('06','Chụp lựa chọn thanh toán mô phỏng và thông báo đặt đơn thành công.')
fig('07','Chụp cùng một đơn lúc Chờ xác nhận và lúc Đang giao hoặc Đã hoàn thành. Giữ mã đơn trong ảnh để đối chiếu.')
page('4 Luồng quản trị viên quản lý danh mục')
feature('4 1 Quản lý nhà hàng','Admin xem danh sách, thêm nhà hàng và xóa nhà hàng. Thông tin thêm gồm tên, địa chỉ và giờ mở cửa. Ứng dụng chọn logo theo tên hãng được hỗ trợ; tên khác dùng biểu tượng chung. Khi xóa nhà hàng, thao tác đồng thời xóa các món và topping liên quan đang được quản lý trong danh mục. Đơn cũ giữ chi tiết món đã đặt qua itemsJson.')
feature('4 2 Quản lý món ăn','Admin thêm món bằng tên, giá và ID nhà hàng được gợi ý trong màn hình. Ứng dụng kiểm tra nhà hàng có tồn tại và kiểm tra giá nhập. Có thể sửa tên, giá, nhà hàng của món; bật hoặc tắt trạng thái còn bán và xóa món. Món mới dùng ảnh chung. Khi xóa món, các topping liên quan cũng được xóa.')
feature('4 3 Quản lý topping','Mỗi topping thuộc một món thông qua foodKey. Admin mở danh sách topping của món, thêm tên và giá cộng thêm hoặc xóa topping không còn dùng. Khách hàng sẽ nhận thay đổi khi mở hoặc đang theo dõi danh mục. Topping trong đơn cũ được giữ trong thông tin lựa chọn tại thời điểm đặt, không tự đổi theo topping mới.')
feature('4 4 Nạp dữ liệu ban đầu','App có chức năng nạp danh mục mẫu khi danh mục còn trống. Tệp demo-catalog.json chứa nhà hàng, món và topping. Nếu danh mục đã có dữ liệu, app không tự ghi đè bằng nút nạp mẫu. Lần bổ sung dữ liệu phục vụ báo cáo dùng thao tác quản trị có sao lưu, giữ lại nhà hàng KFC đã tạo.')
h('4 5 Trình tự thực hiện')
p('Đăng nhập admin → xem danh mục → thêm nhà hàng hoặc chọn nhà hàng đã có → thêm món → cấu hình topping → đăng nhập khách hàng trên thiết bị khác để kiểm tra dữ liệu. Có thể thử đổi giá hoặc tắt bán một món và đối chiếu thay đổi ở màn hình khách hàng.')
fig('08','Chụp danh sách nhà hàng ở màn hình admin, thể hiện logo KFC và Circle K đúng hãng.')
fig('09','Chụp hộp thoại thêm hoặc sửa món và danh sách topping của món đó.')
page('4 Luồng quản trị viên quản lý hệ thống')
feature('4 6 Tài khoản và phân quyền','Admin xem danh sách hồ sơ, tạo tài khoản mới rồi đổi vai trò thành user, shipper hoặc admin theo nhu cầu. Việc tạo tài khoản dùng phiên Firebase phụ để giữ nguyên phiên admin. Tài khoản mới được tạo với vai trò user; thay đổi quyền là thao tác riêng. Nếu lưu hồ sơ thất bại, ứng dụng thử xóa tài khoản Authentication vừa tạo để hạn chế tài khoản thiếu hồ sơ.')
feature('4 7 Khóa và mở khóa','Thao tác khóa cập nhật disabled=true, mở khóa đặt lại false. Đây là khóa truy cập ứng dụng thông qua hồ sơ và Rules, không xóa tài khoản Authentication. Rules không cho admin tự thay đổi vai trò hoặc trạng thái khóa của chính mình. Tài khoản bị khóa có thể vẫn được Authentication xác thực nhưng bị chặn sử dụng dữ liệu nghiệp vụ.')
feature('4 8 Quản lý đơn','Admin xem các đơn của hệ thống, xem thông tin đặt hàng, thay đổi trạng thái và xóa đơn. Quyền này phục vụ quản lý và kiểm tra bài demo. Không có nghiệp vụ hoàn tiền thật khi hủy hoặc xóa đơn. Việc xóa đơn làm thay đổi dữ liệu thống kê vì thống kê được tính từ các đơn còn tồn tại.')
feature('4 9 Thống kê','Màn hình thống kê hiển thị số tài khoản, số món, số đơn và doanh thu từ các đơn Đã hoàn thành. Thống kê món cộng số lượng và tiền theo tên món trong chi tiết đơn hoàn thành. Đây là doanh thu mô phỏng, không phải số tiền đã được một cổng thanh toán xác nhận. Các đơn mẫu hoàn tất cũng được tính vào thống kê.')
h('4 10 Trình tự quản trị')
p('Đăng nhập admin → kiểm tra danh mục → tạo hoặc điều chỉnh quyền tài khoản → xem đơn phát sinh → kiểm tra thống kê. Khi kiểm tra khóa tài khoản, dùng user thử nghiệm, sau đó mở khóa để tiếp tục luồng đặt hàng.')
fig('10','Chụp danh sách tài khoản và lựa chọn đổi vai trò hoặc khóa tài khoản. Không hiển thị mật khẩu.')
fig('11','Chụp màn hình thống kê và một đơn hoàn tất để giải thích nguồn doanh thu.')
page('5 Luồng người giao hàng')
feature('5 1 Danh sách đơn có thể nhận','Shipper xem các đơn có trạng thái Chờ xác nhận và shipperUid còn rỗng. Danh sách không bao gồm đơn đã hủy hoặc đã được nhận. Người giao hàng cần hồ sơ role=shipper và không bị khóa.')
feature('5 2 Nhận đơn','Khi nhận đơn, ứng dụng dùng transaction để kiểm tra lại trạng thái trên Firebase. Chỉ đơn còn chờ và chưa gắn shipper mới được nhận. Ghi thành công sẽ gắn shipperUid, shipperName và đổi trạng thái sang Đang giao. Nếu hai shipper cùng nhận, chỉ một người được xác nhận; người còn lại nhận thông báo đơn đã được nhận hoặc hủy.')
feature('5 3 Theo dõi đơn đang giao','Tab đang giao hiển thị các đơn gắn với UID shipper hiện tại và có trạng thái Đang giao. Nút mô phỏng tăng tiến độ từng bước 20 phần trăm. Sau mỗi lần ghi được xác nhận, bước kế tiếp được lên lịch sau khoảng 1,2 giây. Tốc độ thực tế phụ thuộc mạng. Tiến độ được lưu ở deliveryProgress để các vai trò khác cùng theo dõi.')
feature('5 4 Hoàn tất giao hàng','Mô phỏng đạt 100 phần trăm nghĩa là đã đến nơi; bản thân bước mô phỏng không tự đổi đơn thành Đã hoàn thành. Shipper dùng thao tác hoàn thành để kết thúc đơn. Shipper khác không được hoàn thành một đơn không thuộc mình. Đây không phải định vị GPS hoặc theo dõi đường đi thật.')
feature('5 5 Lịch sử và thu nhập','Lịch sử hiển thị các đơn đã hoàn thành hoặc đã hủy gắn với shipper hiện tại. Thu nhập được tính bằng số đơn hoàn thành nhân 15.000 đồng. Khoản này là quy ước của bài demo, không có ví điện tử hay chức năng rút tiền.')
h('5 6 Trình tự thực hiện')
p('Đăng nhập shipper@gmail.com → mở đơn chờ → nhận một đơn → chuyển sang đang giao → chạy mô phỏng → bấm hoàn thành → xem lịch sử và thu nhập. Đồng thời mở tài khoản khách hàng để đối chiếu mã đơn và trạng thái.')
fig('12','Chụp ba tab đơn chờ, đang giao và lịch sử. Chọn cùng một đơn để minh họa tiến độ 40 phần trăm và trạng thái hoàn tất.')
page('6 Cơ sở dữ liệu và quan hệ')
feature('6 1 Firebase được sử dụng','Project hiện tại là foodnow-app-22dff. Endpoint Realtime Database là https://foodnow-app-22dff-default-rtdb.asia-southeast1.firebasedatabase.app. Authentication lưu thông tin xác thực; Realtime Database lưu dữ liệu nghiệp vụ. File google-services.json cấu hình ứng dụng Android với project này.')
feature('6 2 Cấu trúc cấp cao','Realtime Database là cây JSON, không phải hệ quản trị bảng SQL. Năm nhánh nghiệp vụ là users, restaurants, foods, options và orders. UID từ Authentication là khóa hồ sơ users. Các bản ghi thông thường dùng khóa Firebase; bộ dữ liệu mẫu có một số khóa dễ nhận biết như demo-f1 hoặc demo-order-v1-1.')
table(['Quan hệ','Trường liên kết','Ý nghĩa'],[['Authentication → users','UID = khóa users','Một tài khoản có hồ sơ theo UID'],['restaurants → foods','foods.restaurantKey','Một nhà hàng có nhiều món'],['foods → options','options.foodKey','Một món có nhiều topping'],['users → orders','orders.ownerUid','Một khách hàng có nhiều đơn'],['users → orders','orders.shipperUid','Một shipper được gắn nhiều đơn'],['orders → chi tiết món','orders.itemsJson','Chuỗi JSON chứa danh sách món tại lúc đặt']])
feature('6 3 Khóa dữ liệu và ID trên giao diện','Một số màn hình cũ dùng số nguyên để hiển thị hoặc chọn ID. CloudRepository ánh xạ số nguyên đó sang khóa Firebase thật trong bộ nhớ. Khi ghi dữ liệu, ứng dụng dùng khóa Firebase hoặc UID, không dùng số thứ tự hiển thị làm khóa lâu dài. Vì vậy không lấy ID số trên màn hình để tự tạo hồ sơ Authentication.')
feature('6 4 Vai trò của SQLite','Mã DatabaseHelper và xử lý mật khẩu cũ vẫn còn trong dự án, nhưng các màn hình nghiệp vụ hiện dùng CloudRepository và Firebase làm nguồn dữ liệu chính. Không cần chép một file SQLite giữa các thiết bị để chia sẻ dữ liệu. Cơ chế băm mật khẩu cũ không thay thế Firebase Authentication trong luồng đăng nhập hiện tại.')
fig('13','Chụp Firebase Console của đúng project, mở đủ năm nhánh dữ liệu. Chụp thêm Authentication để đối chiếu UID với users.')
